import {initialCafe,validateCafe,reduceCafe} from './cafe-state.js';
import {POST_RECIPIENTS,POST_TEMPLATES} from './postcards.js';
import {WALL_SLOTS,MAX_PHOTOS,cleanPhoto} from './photo-config.js';
export const initialVillage=()=>({cafe:initialCafe(),bakery:{phase:'empty',decoration:null,completed:0,pastries:0},mailbox:{letters:[]},photos:[],wallPlacements:{}});
export function validateVillage(raw){const s=raw===undefined?initialVillage():raw;if(!s||typeof s!=='object'||Array.isArray(s))return null;const b=s.bakery;if(!b||!['empty','dough','baked','complete'].includes(b.phase)||!Number.isSafeInteger(b.completed)||b.completed<0||b.completed>999||!Number.isSafeInteger(b.pastries)||b.pastries<0||b.pastries>b.completed)return null;if(b.phase==='complete'?!['berry','star'].includes(b.decoration)||b.completed<1:b.decoration!==null)return null;
 const mailbox=s.mailbox??{letters:[]};if(!mailbox||!Array.isArray(mailbox.letters)||mailbox.letters.length>9)return null;const letters=[];for(const l of mailbox.letters){if(!l||!Object.hasOwn(POST_RECIPIENTS,l.recipient)||!Object.hasOwn(POST_TEMPLATES,l.template)||l.id!==l.recipient+'.'+l.template||typeof l.gift!=='boolean'||typeof l.read!=='boolean'||letters.some(o=>o.id===l.id))return null;letters.push({id:l.id,recipient:l.recipient,template:l.template,gift:l.gift,read:l.read});}if(b.completed-letters.filter(l=>l.gift).length!==b.pastries)return null;
 const photos=s.photos??[],placements=s.wallPlacements??{};if(!Array.isArray(photos)||photos.length>MAX_PHOTOS||photos.some(p=>!cleanPhoto(p))||new Set(photos.map(p=>p.id)).size!==photos.length||!placements||typeof placements!=='object'||Array.isArray(placements)||Object.entries(placements).some(([slot,id])=>!Object.hasOwn(WALL_SLOTS,slot)||!photos.some(p=>p.id===id)))return null;
 const cafe=validateCafe(s.cafe);if(!cafe)return null;
 return {cafe,bakery:{phase:b.phase,decoration:b.decoration,completed:b.completed,pastries:b.pastries},mailbox:{letters},photos:photos.map(cleanPhoto),wallPlacements:{...placements}};}
export function reduceVillage(state=initialVillage(),action){if(action.type?.startsWith('CAFE_')){const previous=state.cafe??initialCafe(),cafe=reduceCafe(previous,action);return cafe===previous?state:{...state,cafe};}const b=state.bakery;let next;switch(action.type){
 case 'BAKE_DOUGH':if(b.phase==='empty'&&b.completed<999)next={...b,phase:'dough'};break;
 case 'BAKE_OVEN':if(b.phase==='dough')next={...b,phase:'baked'};break;
 case 'BAKE_DECORATE':if(b.phase==='baked'&&['berry','star'].includes(action.decoration)&&b.completed<999)next={...b,phase:'complete',decoration:action.decoration,completed:b.completed+1,pastries:b.pastries+1};break;
 case 'BAKE_NEW':if(b.phase==='complete'&&b.completed<999)next={...b,phase:'empty',decoration:null};break;
 case 'SEND_POSTCARD':{const {recipient,template}=action,gift=action.gift===true,id=recipient+'.'+template;if(!Object.hasOwn(POST_RECIPIENTS,recipient)||!Object.hasOwn(POST_TEMPLATES,template)||state.mailbox.letters.some(l=>l.id===id)||(gift&&b.pastries<1))return state;return {...state,bakery:gift?{...b,pastries:b.pastries-1}:b,mailbox:{letters:[...state.mailbox.letters,{id,recipient,template,gift,read:false}]}};}
 case 'READ_POSTCARD':{if(!state.mailbox.letters.some(l=>l.id===action.id&&!l.read))return state;return {...state,mailbox:{letters:state.mailbox.letters.map(l=>l.id===action.id?{...l,read:true}:l)}};}
 case 'ADD_PHOTO':{const p=cleanPhoto(action.photo);if(!p||state.photos.length>=MAX_PHOTOS||state.photos.some(x=>x.id===p.id))return state;return {...state,photos:[...state.photos,p]};}
 case 'PLACE_PHOTO':{if(!Object.hasOwn(WALL_SLOTS,action.slotId)||!state.photos.some(p=>p.id===action.photoId)||state.wallPlacements[action.slotId]===action.photoId)return state;return {...state,wallPlacements:{...state.wallPlacements,[action.slotId]:action.photoId}};}
 case 'REMOVE_WALL_PHOTO':{if(!Object.hasOwn(state.wallPlacements,action.slotId))return state;const wallPlacements={...state.wallPlacements};delete wallPlacements[action.slotId];return {...state,wallPlacements};}
 case 'REMOVE_PHOTO':{if(!state.photos.some(p=>p.id===action.photoId))return state;return {...state,photos:state.photos.filter(p=>p.id!==action.photoId),wallPlacements:Object.fromEntries(Object.entries(state.wallPlacements).filter(([,id])=>id!==action.photoId))};}
 }return next?{...state,bakery:next}:state;}
